const cxCode = e => { let h = 0x811c9dc5; const s = [CX_SALT, e.id, e.summary || '', (e.start && (e.start.dateTime || e.start.date)) || '', (e.end && (e.end.dateTime || e.end.date)) || '', cxRoom(e)].join('|');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
let prepareMode = String(REQ.mode || '').toLowerCase() === 'prepare';
const wantCode = String(REQ.check_code || '').trim().toLowerCase();
// Levenshtein distance, used only to recognise a title the model mistyped.
const dist = (a, b) => {
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
};
// Two bookings can share a title on one day, so a list of them has to carry the
// time or there is nothing to choose between.
const when = e => {
  const s = (e.start && e.start.dateTime) || '';
  if (!s) return '(all day)';
  const d = new Date(s);
  return '(' + d.toLocaleTimeString('en-US', { timeZone:'Asia/Manila', hour:'numeric', minute:'2-digit' }) + ')';
};

// v19 (29 Sep QA): an unconfirmed call used to answer NOT_CONFIRMED and tell the model to show the booking itself - so it
// wrote its own card (with a raw Event ID) for a booking the requester could not cancel, and the refusal came only at
// the yes. Now it is Prepare Cancel: the booking is found, ownership is checked first, then the code-written card.
if (!confirmed && !prepareMode) prepareMode = true;
if (!String(REQ.booking_date || '').trim()) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DATE',
    human:'Nothing was cancelled - no booking date was given. Call Cancel Booking again with the date you showed the requester.' } }];
}
if (!wantedId && !wantedTitle) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DETAILS',
    human:'Nothing was cancelled - no booking title or event id was given. Call Cancel Booking again with the title exactly as you showed it to the requester.' } }];
}

// A second page (nextPageToken) means this read is incomplete: refuse rather than miss a booking (review 29 Sep).
const items = Array.isArray(raw.items) && !raw.nextPageToken ? raw.items.filter(e => e.status !== 'cancelled') : null;
if (!items) {
  return [{ json: { verdict:'REJECTED', reason:'LOOKUP_FAILED',
    human:'Nothing was cancelled - the calendar could not be read for that date. Tell the requester it did not go through and offer to try again.' } }];
}

// The id if it is real, otherwise the title. An invented id no longer dead-ends
// a cancellation that named the booking correctly.
let ev = wantedId ? items.find(e => String(e.id) === wantedId) : null;
let how = ev ? 'id' : '';
