  // A yes to a prepared card: only the booking of that exact title whose current details still give the card's
  // code. The model's event id is not used on this path.
  const same = items.filter(e => norm(e.summary) && norm(e.summary) === norm(wantedTitle));
  ev = same.find(e => cxCode(e) === wantCode) || null; how = ev ? 'card' : '';
  if (!ev) return [{ json: { verdict:'REJECTED', reason: same.length ? 'CHANGED' : 'NOT_ON_CALENDAR', title: wantedTitle,
    human: same.length ? 'Nothing was cancelled - that booking has changed since the card was shown. Show the current details and ask again.'
                       : 'Nothing was cancelled - that booking is no longer on the calendar.' } }];
}
if (!ev && wantedTitle) {
  const want = norm(wantedTitle);
  // Only a titled booking can match a title: an untitled event used to match every request, because
  // want.includes('') is always true (review 29 Sep). Only ONE exact title is acted on.
  const titled = items.filter(e => norm(e.summary));
  const hits = titled.filter(e => norm(e.summary) === want);
  if (hits.length === 1) { ev = hits[0]; how = 'title'; }
  else if (hits.length > 1) {
    return [{ json: { verdict:'REJECTED', reason:'AMBIGUOUS_TITLE',
      human: 'Nothing was cancelled - more than one booking on that date is titled "' + wantedTitle + '":\n'
        + hits.map(e => '- ' + e.summary + ' ' + when(e)).join('\n')
        + '\nAsk the requester which one they mean, then call Cancel Booking again with that exact title.' } }];
  }
  else {
    // A partial or near title is shown back, never acted on. The model does corrupt titles it copies back
    // ("REazon1" for "REASON1", 2026-08-30), but a near title can also be a different episode or project
    // the same day - and a wrong booking cannot be un-cancelled.
    const tol = Math.max(1, Math.floor(want.length * 0.15));
    const cands = titled.filter(e => { const t = norm(e.summary); return t.includes(want) || want.includes(t) || dist(t, want) <= tol; });
    if (cands.length) {
    return [{ json: { verdict:'REJECTED', reason:'AMBIGUOUS_TITLE',
      human: 'Nothing was cancelled - no booking on that date is titled exactly "' + wantedTitle + '". Closest:\n'
        + cands.map(e => '- ' + e.summary + ' ' + when(e)).join('\n')
        + '\nShow the requester the booking you mean with its exact title and ask them to confirm it (end with "Confirm to cancel. (yes/no)"). Only after they reply yes, call Cancel Booking again with that exact title.' } }];
  }
  }
}
if (!ev) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_ON_CALENDAR',
    human: 'Nothing was cancelled - no booking on that date matches what you gave. These are the only bookings on '
      + 'that date:\n' + (items.map(e => '- ' + (e.summary || '(no title)') + ' ' + when(e)).join('\n') || '(none)')
      + '\nIf one of them is the booking, call Cancel Booking again with that title exactly. If none of them is, '
      + 'tell the requester it was not found and ask them to check the date.' } }];
}

const desc = String(ev.description || '');
const ref  = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by   = desc.match(/Booked by:\s*([^|]+)/);
const who  = by ? by[1].trim() : '';
const title = ev.summary || '(no title)';

if (!ref) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE', title,
    human:'BLOCKED - "' + title + '" carries no booker reference, so there is no way to tell whose it is. It has to be cancelled by hand.' } }];
}
// Rule-1 exception: an authorized coordinator may cancel a booking in their own department
// ('Dept Head' or 'Client Booking'); a HAIST Dev may cancel any booking, any department (isHaistDev
// below). Same check as Move Booking. See docs/design/booking-authority.md.
const authStr = String(REQ.authority || '').toLowerCase();
const isCoord = authStr.indexOf('dept head') !== -1 || authStr.indexOf('client booking') !== -1;
const myDepts = String(REQ.department || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const bookingDept = ((desc.match(/Dept:\s*([^|]+)/) || [])[1] || '').toLowerCase().trim();
const owner = ref[1] === me;
const isHaistDev = authStr.indexOf('haist dev') !== -1;
const coordInDept = isCoord && !!bookingDept && myDepts.indexOf(bookingDept) !== -1;
if (!(owner || isHaistDev || coordInDept)) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_YOURS', title,
    human:'BLOCKED - "' + title + '" was booked by ' + (who || 'someone else') + ', and you do not have authority to cancel it. Say exactly that to the requester and stop. Do not search again and do not show the booking again.' } }];
}
// Notify the booker (and the assigned engineer, resolved downstream) when a
// coordinator - not the owner - cancels their booking. Composition + the dev
// redirect live in Build Recipients so they are unit-testable. See EOD-2026-09-19.
if (prepareMode) {
  // Nothing is deleted in prepare mode: the requester sees exactly this card, and their yes cancels exactly it.
  const s = (ev.start && (ev.start.dateTime || ev.start.date)) || '', en = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
  const allDay = !(ev.start && ev.start.dateTime);
  const D = allDay ? new Date(s + 'T00:00:00+08:00') : new Date(s);
  const date = D.toLocaleDateString('en-US', { timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
  const t = x => new Date(x).toLocaleTimeString('en-US', { timeZone: 'Asia/Manila', hour: 'numeric', minute: '2-digit' });
  const time = allDay ? 'All day' : (t(s) + ' – ' + t(en));
  const room = cxRoom(ev) || '(no room on the booking)';
  const card = ['*' + title + '*', '*Date:* ' + date, '*Time:* ' + time, '*Room:* ' + room, '*Booked by:* ' + (who || 'unknown'),
    '_check ' + cxCode(ev) + '_', '', 'Reply only with "yes" to cancel, or "no" to keep it.', 'Confirm to cancel.'].join('\n');   // as Guard Probe sends it
  return [{ json: { verdict:'PREPARED', status:'PREPARED', event_id: ev.id, title, card_text: card,
    human:'Send the requester this card as your whole reply, exactly as it is, and stop. Their yes cancels it.' } }];
}
const notify = !owner && (coordInDept || isHaistDev);
const bookerRef = ref[1];
const bookerName = who || 'the booker';
const engInitials = (title.split('/').pop() || '').trim();
const engName = ((desc.match(/Engineer:\s*([^(|]+)/) || [])[1] || '').trim();
const _q = s => String(s).replace(/"/g, '');
const _p = [];
if (engInitials) _p.push('{Initials} = "' + _q(engInitials) + '"');
if (engName) _p.push('LOWER({Name}) = "' + _q(engName).toLowerCase() + '"');
const engFilter = _p.length === 0 ? 'FALSE()' : (_p.length === 1 ? _p[0] : 'OR(' + _p.join(', ') + ')');
return [{ json: { verdict:'CLEAR', event_id: ev.id, title, matched_on: how,
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
  notify, bookerRef, bookerName, engInitials, engFilter } }];

const c = $('Check Ownership').first().json;
return [{ json: { status:'CANCELLED', event_id: c.event_id, title: c.title,
  human:'Cancelled "' + c.title + '".' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was cancelled and the reason is unclear. Tell the requester it did not go through.' } }];

// Notification recipients for an authorized change: the booker (owner) always, plus the
// assigned engineer when distinct. DEV_REDIRECT reroutes to one dev inbox while building.
// ALLOW = ids that receive their OWN real DM instead of the redirect - but only as the
// BOOKER always honors ALLOW (honorAllow=true). ENGINEER honors ALLOW too as of QA round 2
// 2026-09-24 (was always-redirect) - so a listed tester assigned as engineer (e.g. Tara) gets
// the engineer notice; non-listed people still redirect. At launch DEV_REDIRECT='' -> all real.
const DEV_REDIRECT = 'U08V3CKDGJF';                 // '' at launch
const ALLOW = ['U08V3CKDGJF','U098UFMKQHZ','U08JL17A50A','U0B4S0EKSAY','U098UFLG70B','U026N6E1R','U045A3VQER3'] /* QA round 2 2026-09-24: Howard,Trish,Camy,Jess,Tel,Tara,Genzo. Launch bypass = DEV_REDIRECT='' (ALLOW then moot). */ ;
const route = (id, honorAllow) => (!DEV_REDIRECT || (honorAllow && ALLOW.indexOf(id) !== -1)) ? id : DEV_REDIRECT;
const co = $('Check Ownership').first().json;
const trig = $('When Executed by Another Workflow').first().json;
const actor = String(trig.requester_name || 'a coordinator');
const actorId = String(trig.requester || '');
const dateStr = String(trig.booking_date || '');
const title = co.title;
const VERB = 'cancelled';
const roomNote = '';
const out = [];
const push = (id, name, body, honorAllow) => {
  const to = route(id, honorAllow); const redirected = to !== id;
  out.push({ to, text: (redirected ? ('[DEV] would notify ' + name + ' (' + id + '):\n') : '') + body });
};
const bookerId = co.bookerRef;
const bookerName = co.bookerName || 'the booker';
push(bookerId, bookerName, 'Heads up - your booking "' + title + '" on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', true);
let eng = {};
try { eng = $('Lookup Engineer').first().json || {}; } catch (e) {}
const ef = eng.fields || {};
const engId = ef['Slack User ID'] || '';
const engName = ef['Name'] || '';
if (engId && engId !== bookerId && engId !== actorId) {
  push(engId, engName, 'Heads up - the session "' + title + '" you are assigned to on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', true);
}
return out.map(o => ({ json: o }));

function manila(iso){ const d=iso?new Date(iso):new Date();
  const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d).reduce((o,x)=>(o[x.type]=x.value,o),{});
  return p.year+'-'+p.month+'-'+p.day+' '+p.hour+':'+p.minute; }
function dateOnly(iso){ try{ return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso)); }catch(e){ return ''; } }
function timeRange(a,b){ const f=iso=>{ try{ return new Date(iso).toLocaleTimeString('en-US',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}); }catch(e){ return ''; } };
  const s=f(a),e=f(b); return (s&&e)?(s+' \u2013 '+e):''; }

const CO = $('Check Ownership').first().json || {};
const REQ = $('When Executed by Another Workflow').first().json || {};
return [{ json: {
  'Timestamp': manila(),
  'Action': 'CANCELLED',
  'Title': String(CO.title || ''),
  'Room(s)': '',
  'Date': String(REQ.booking_date || ''),
  'Time': timeRange(CO.start, ''),
  'Department': '',
  'Booker': String(CO.bookerName || ''),
  'Done by': String(REQ.requester_name || CO.bookerName || ''),
